import { MODELO_PROYECCION, MODELO_CINE } from '../../models/cine-proyeccion.model.mjs';

export async function trasladarProyeccionRepository(proyeccionId, cineId) {
  const { Attributes } = await MODELO_PROYECCION.build(EntityRepository).update(
    { proyeccionId, cineId },
    {
      condition: { attr: 'proyeccionId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { consultarCineService } from './service.mjs';

export async function handler(event) {
  const cineId = Number(event.pathParameters.cineId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarCineService(cineId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarCineRepository, consultarCineRepository } from './repository.mjs';

export async function consultarCineService(cineId, minimo) {
  const cine = await buscarCineRepository(cineId);
  if (!cine) throw new Error('Cine no encontrado');
  const proyecciones = await consultarCineRepository(cineId, minimo);
  return { cine, proyecciones };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_PROYECCION, MODELO_CINE } from '../../models/cine-proyeccion.model.mjs';

export async function buscarCineRepository(cineId) {
  const { Item } = await MODELO_CINE.build(EntityRepository).get(
    { cineId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarCineRepository(cineId, minimo) {
  const { Items = [] } = await MODELO_PROYECCION.build(EntityRepository).query(
    { index: 'PorCine', partition: cineId },
    { filters: { Proyeccion: { attr: 'duracionMinutos', gte: minimo } } }
  );
  return Items;
}
